param([switch]$Preflight)
$ErrorActionPreference='Stop'
if($Preflight){[ordered]@{schema='argos_o2a3_processor_process_observation_preflight_v1';state='PASS_O2A3_PROCESSOR_PROCESS_OBSERVATION_PREFLIGHT';targetExecuted=$false;mutationsPerformed=$false}|ConvertTo-Json;return}
$token='Run-JbodAllWaferProcessor.ps1'
$rows=@(Get-CimInstance Win32_Process -ErrorAction Stop|Where-Object{$_.ProcessId-in@(2352,3556,11008,8504)-or($null-ne$_.CommandLine-and$_.CommandLine.IndexOf($token,[StringComparison]::OrdinalIgnoreCase)-ge 0)}|Sort-Object ProcessId|Select-Object -First 8|ForEach-Object{$o=Invoke-CimMethod -InputObject $_ -MethodName GetOwner -ErrorAction SilentlyContinue;[ordered]@{processId=[int64]$_.ProcessId;parentProcessId=[int64]$_.ParentProcessId;name=[string]$_.Name;sessionId=[int64]$_.SessionId;executablePath=[string]$_.ExecutablePath;commandLine=[string]$_.CommandLine;creationDate=if($null-eq$_.CreationDate){''}else{([DateTime]$_.CreationDate).ToUniversalTime().ToString('o')};owner=if($null-eq$o-or$o.ReturnValue-ne 0){''}else{[string]$o.Domain+'\'+[string]$o.User};ownerReturnValue=if($null-eq$o){-1}else{[int]$o.ReturnValue}}})
[ordered]@{schema='argos_o2a3_processor_process_observation_v1';state='PASS_O2A3_PROCESSOR_PROCESS_OBSERVATION';computerName=$env:COMPUTERNAME;processorCommandToken=$token;tokenMatchCount=@($rows|Where-Object{-not[string]::IsNullOrEmpty($_.commandLine)-and$_.commandLine.IndexOf($token,[StringComparison]::OrdinalIgnoreCase)-ge 0}).Count;processes=$rows;imageBytesRead=$false;taskOrProcessRestarted=$false;mutationsPerformed=$false;reviewOnly=$true;productionRoutingEnabled=$false}|ConvertTo-Json -Depth 6
